	[30099] = {
		name = "完美合奏",
		id = 30099,
		type = 5,
		compose_id = 0,
		rare = 5,
		desc = "不灭王权·荷鲁斯的换装「完美合奏」。\n——一款清新舒适的居家常服，设计上采用了荷鲁斯和管理员的一些巧思。荷鲁斯对它的配色和质感都非常满意，在排练的日子里几乎都穿着这套衣服。\n「谁说练习的时候不能这么穿了？我一样能弹出超厉害的曲子！」",
